return $input.all().map(item => {
  const data = item.json;

  const fileId = data.id || '';
  const fileName = data.name || '';
  const mimeType = data.mimeType || '';
  const size = Number(data.size) || 0;
  const extension = data.fileExtension
    ? data.fileExtension.toLowerCase()
    : (fileName.includes('.') ? fileName.split('.').pop().toLowerCase() : '');

  let isToday = false;
  if (data.createdTime) {
    const fileDate = new Date(data.createdTime);
    fileDate.setHours(0, 0, 0, 0);
    const today = new Date();
    today.setHours(0, 0, 0, 0);
    isToday = fileDate.getTime() === today.getTime();
  }

  return {
    json: {
      id: fileId,
      Nombre: fileName,
      Tipo: mimeType,
      Extension: extension,
      Tamaño_bytes: size,
      Tamaño_MB: size > 0 ? (size / 1048576).toFixed(2) + ' MB' : '—',
      Creado: data.createdTime ? new Date(data.createdTime).toISOString().split('T')[0] : '',
      Modificado: data.modifiedTime ? new Date(data.modifiedTime).toISOString().split('T')[0] : '',
      Ultima_Actualizacion: new Date().toISOString(),
      Today_Create: isToday,
      Upload: false
    }
  };
});

